/// <summary>
///     AVA <c>avaConvertValueCheck</c> method.
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean avaConvertValueCheck()
{
    boolean ret;

    ret = true; 

    if (this.validateParameters())
    {
        if (fromUnitOfMeasure != toUnitOfMeasure)
        {
            // Find conversion
            this.findConversion();
            if (unitOfMeasureConversionCache.ConversionExists   == NoYes::Yes)
            {
                if(     unitOfMeasureConversionCache.FactorDenominator  == 0
                    ||  unitOfMeasureConversionCache.Denominator        == 0)
                {
                    ret = false;
                }
            }
        }
    }

    return ret;
}
